public static double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Find the number of elements to be removed from the smallest and largest ends
    int removeSmall = (int) Math.ceil(arr.length * 0.05);
    int removeLarge = (int) Math.ceil(arr.length * 0.05);

    // Sum the remaining elements after removing the smallest and largest ends
    double sum = 0;
    for (int i = removeSmall; i < arr.length - removeLarge; i++) {
        sum += arr[i];
    }

    // Calculate the mean with error within 10^-5
    return sum / (arr.length - removeSmall - removeLarge);
}

public double trimMean(int[] arr) {
    int n = arr.length;
    int n05 = (int) Math.floor(n / 20);
    int n15 = (int) Math.ceil(n * 15 / 100);

    Arrays.sort(arr);
    int[] arr05 = Arrays.copyOfRange(arr, n05, n - n05);
    int[] arr15 = Arrays.copyOfRange(arr, n15, n - n15);

    double sum = 0;
    for (int i = 0; i < arr05.length; i++) {
        sum += arr05[i];
    }
    for (int i = 0; i < arr15.length; i++) {
        sum += arr15[i];
    }

    return sum / (arr05.length + arr15.length);
}

public double trimMean(int[] arr) {
      Arrays.sort(arr);
      double trimFactor = 0.05;
      int numElements = (int) (arr.length * (1 - trimFactor * 2));
      double sum = 0;
      for (int i = (int) (trimFactor * arr.length); i < numElements; i++) {
          sum += arr[i];
      }
      return sum / numElements;
  }

public double trimMean(int[] arr) {
    double mean = 0.0;

    // Calculate the mean of the array
    for (int i = 0; i < arr.length; i++) {
        mean += (double) arr[i] / arr.length;
    }

    // Calculate the 5% percentile
    int n = (int) (arr.length * 0.05);
    Arrays.sort(arr);
    int low = n;
    int high = arr.length - n - 1;

    // Calculate the mean of the remaining elements after removing the smallest 5% and largest 5%
    for (int i = low; i <= high; i++) {
        mean += (double) arr[i] / (arr.length - 2 * n);
    }

    return mean;
}

public double trimMean(int[] arr) {
    double mean = 0;

    // Sort the array in ascending order
    Arrays.sort(arr);

    // Remove the smallest 5% and largest 5% of the elements
    int numToRemove = (int) (arr.length * 0.05);
    arr = Arrays.copyOfRange(arr, numToRemove, arr.length - numToRemove);

    // Calculate the mean of the remaining elements
    for (int num : arr) {
        mean += num;
    }
    mean /= arr.length;

    return mean;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int[] counts = new int[k];
    for (int i = 0; i < n; i++) {
        int num = arr[i];
        int j = num % k;
        if (j == 0) j = k;
        counts[j-1]++;
    }
    for (int i = 0; i < k; i++) {
        if (counts[i]*2 != n) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length / 2;
    int[] counts = new int[k];
    for (int i = 0; i < n; i++) {
        int a = arr[i];
        int b = arr[i + n];
        int sum = a + b;
        counts[sum % k]++;
    }
    for (int i = 1; i < k; i++) {
        if (counts[i] != counts[k - i]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length / 2;
    boolean[] isEven = new boolean[n];
    for (int i = 0; i < n; i++) {
        isEven[i] = false;
    }
    for (int i = 0; i < arr.length; i++) {
        int sum = arr[i] + arr[(i + 1) % arr.length];
        for (int j = 0; j < n; j++) {
            if (sum % k == 0) {
                isEven[j] = true;
                break;
            }
        }
    }
    for (boolean b : isEven) {
        if (!b) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    Arrays.sort(arr);
    int[] sums = new int[n / 2];
    for (int i = 0, j = n - 1; i < n / 2; i++, j--) {
        sums[i] = arr[i] + arr[j];
    }
    Arrays.sort(sums);
    for (int i = 0; i < n / 2; i++) {
        if (sums[i] % k != 0) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    Arrays.sort(arr);
    int sum = 0;
    for (int i = 0; i < n / 2; i++) {
        sum += arr[i] + arr[n - 1 - i];
    }
    return sum % k == 0;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distance = new int[n];
    Arrays.fill(distance, Integer.MAX_VALUE);
    distance[0] = 0;
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < edges.length; j++) {
            int node1 = edges[j][0];
            int node2 = edges[j][1];
            if (distance[node1] < Integer.MAX_VALUE && distance[node2] > distance[node1] + (hasApple[node2] ? 2 : 1)) {
                distance[node2] = distance[node1] + (hasApple[node2] ? 2 : 1);
            }
        }
    }
    return distance[n - 1];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distances = new int[n];
    Arrays.fill(distances, Integer.MAX_VALUE);
    distances[0] = 0;

    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < edges.length; j++) {
            int u = edges[j][0];
            int v = edges[j][1];
            if (distances[u] != Integer.MAX_VALUE && distances[v] > distances[u] + 1) {
                distances[v] = distances[u] + 1;
            }
        }
    }

    int minTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            minTime += distances[i];
        }
    }

    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distances = new int[n];
    int[] parents = new int[n];
    for (int i = 0; i < n; i++) {
        distances[i] = Integer.MAX_VALUE;
        parents[i] = -1;
    }
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    distances[0] = 0;
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int i = 0; i < edges[node].length; i++) {
            int neighbor = edges[node][i];
            if (distances[neighbor] > distances[node] + 1) {
                distances[neighbor] = distances[node] + 1;
                parents[neighbor] = node;
                queue.offer(neighbor);
            }
        }
    }
    int minTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            minTime += distances[i];
        }
    }
    return minTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distances = new int[n];
    Arrays.fill(distances, Integer.MAX_VALUE);
    distances[0] = 0;

    for (int i = 0; i < n - 1; i++) {
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            if (distances[u] != Integer.MAX_VALUE && distances[v] > distances[u] + 1) {
                distances[v] = distances[u] + 1;
            }
        }
    }

    int totalTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            totalTime += distances[i];
        }
    }

    return totalTime;
}

