            }
        }
    }
    return time;
}

public String sortString(String s) {
    String result = "";
    while (s.length() > 0) {
        // Step 1: Pick the smallest character from s and append it to the result
        char smallest = s.charAt(0);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < smallest) {
                smallest = s.charAt(i);
            }
        }
        result += smallest;
        s = s.replaceFirst(String.valueOf(smallest), "");

        // Step 2: Pick the smallest character from s which is greater than the last appended character to the result and append it
        char smallestGreater = Character.MAX_VALUE;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) > smallest && s.charAt(i) < smallestGreater) {
                smallestGreater = s.charAt(i);
            }
        }
        if (smallestGreater != Character.MAX_VALUE) {
            result += smallestGreater;
            s = s.replaceFirst(String.valueOf(smallestGreater), "");
        }

        // Step 3: Repeat step 2 until you cannot pick more characters
        while (smallestGreater != Character.MAX_VALUE) {
            smallestGreater = Character.MAX_VALUE;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) > smallest && s.charAt(i) < smallestGreater) {
                    smallestGreater = s.charAt(i);
                }
            }
            if (smallestGreater != Character.MAX_VALUE) {
                result += smallestGreater;
                s = s.replaceFirst(String.valueOf(smallestGreater), "");
            }
        }

        // Step 4: Pick the largest character from s and append it to the result
        char largest = s.charAt(0);
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) > largest) {
                largest = s.charAt(i);
            }
        }
        result += largest;
        s = s.replaceFirst(String.valueOf(largest), "");

        // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it
        char largestSmaller = Character.MIN_VALUE;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) < largest && s.charAt(i) > largestSmaller) {
                largestSmaller = s.charAt(i);
            }
        }
        if (largestSmaller != Character.MIN_VALUE) {
            result += largestSmaller;
            s = s.replaceFirst(String.valueOf(largestSmaller), "");
        }

        // Step 6: Repeat step 5 until you cannot pick more characters
        while (largestSmaller != Character.MIN_VALUE) {
            largestSmaller = Character.MIN_VALUE;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) < largest && s.charAt(i) > largestSmaller) {
                    largestSmaller = s.charAt(i);
                }
            }
            if (largestSmaller != Character.MIN_VALUE) {
                result += largestSmaller;
                s = s.replaceFirst(String.valueOf(largestSmaller), "");
            }
        }
    }
    return result;
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    String result = "";
    for (int i = 0; i < chars.length; i++) {
        char c = chars[i];
        if (i % 2 == 0) {
            result += c;
        }
    }
    for (int i = chars.length - 1; i >= 0; i--) {
        char c = chars[i];
        if (i % 2 != 0) {
            result += c;
        }
    }
    return result;
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();

    // Step 1: pick the smallest character and append it to the result
    for (char c : chars) {
        if (c == 'a') {
            break;
        }
        result.append(c);
    }

    // Step 2: pick the smallest character that is greater than the last appended character and append it
    for (char c : chars) {
        if (c == 'c') {
            break;
        }
        if (c > result.charAt(result.length() - 1)) {
            result.append(c);
        }
    }

    // Step 3: repeat step 2 until you cannot pick more characters
    for (int i = result.length(); i < s.length(); i++) {
        boolean found = false;
        for (char c : chars) {
            if (c > result.charAt(result.length() - 1)) {
                result.append(c);
                found = true;
                break;
            }
        }
        if (!found) {
            break;
        }
    }

    // Step 4: pick the largest character and append it to the result
    for (int i = s.length() - 1; i >= 0; i--) {
        if (chars[i] == 'z') {
            break;
        }
        result.append(chars[i]);
    }

    // Step 5: pick the largest character that is smaller than the last appended character and append it
    for (int i = s.length() - 1; i >= 0; i--) {
        if (chars[i] == 'a') {
            break;
        }
        if (chars[i] < result.charAt(result.length() - 1)) {
            result.append(chars[i]);
        }
    }

    // Step 6: repeat step 5 until you cannot pick more characters
    for (int i = result.length(); i < s.length(); i++) {
        boolean found = false;
        for (int j = s.length() - 1; j >= 0; j--) {
            if (chars[j] < result.charAt(result.length() - 1)) {
                result.append(chars[j]);
                found = true;
                break;
            }
        }
        if (!found) {
            break;
        }
    }

    return result.toString();
}

