public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    for (int i = 1; i < n; i++) {
        if (sum * 2 % n != sum) {
            return false;
        }
        sum *= 2;
    }
    return true;
}

public boolean splitArraySameAverage(int[] nums) {
    double total = 0;
    for (int num : nums) {
        total += num;
    }
    double average = total / nums.length;
    double firstHalfSum = 0;
    double secondHalfSum = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        firstHalfSum += nums[i];
    }
    for (int i = nums.length / 2; i < nums.length; i++) {
        secondHalfSum += nums[i];
    }
    return firstHalfSum / (nums.length / 2) == secondHalfSum / (nums.length - nums.length / 2)
        && firstHalfSum / (nums.length / 2) == average;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return false;
    }
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    double halfAvg = (double) sum / 2;
    double currentSum = 0;
    for (int i = 0; i < n; i++) {
        currentSum += nums[i];
        if (currentSum == halfAvg) {
            return true;
        } else if (currentSum > halfAvg) {
            return false;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    double total = 0;
    for (int num : nums) {
        total += num;
    }
    double average = total / nums.length;
    double leftSum = 0;
    double rightSum = 0;
    int leftIndex = 1;
    int rightIndex = nums.length - 1;
    while (leftIndex <= rightIndex) {
        leftSum += nums[leftIndex];
        rightSum += nums[rightIndex];
        if (leftSum == rightSum) {
            return true;
        }
        if (leftSum > rightSum) {
            return false;
        }
        leftIndex++;
        rightIndex--;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums.length % 2 != 0) return false;
    int n = nums.length / 2;
    double sum1 = 0, sum2 = 0;
    for (int i = 0; i < n; i++) {
        sum1 += nums[i];
    }
    for (int i = n; i < nums.length; i++) {
        sum2 += nums[i];
    }
    return sum1 == sum2;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int dp0 = cost[0];
    int dp1 = cost[1];
    for (int i = 2; i < n; i++) {
        int dp2 = Math.min(dp0, dp1) + cost[i];
        dp0 = dp1;
        dp1 = dp2;
    }
    return Math.min(dp0, dp1);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i];
    }
    return Math.min(dp[n-1], dp[n-2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n];
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            dp[i] = cost[i];
        } else if (i == 1) {
            dp[i] = cost[i] + cost[i - 1];
        } else {
            dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
        }
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

