public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] dp = new int[n];
    Set<String> seen = new HashSet<>();
    seen.add(s);
    dp[0] = 1;
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (s.charAt(i) != s.charAt(j)) {
                String sub = s.substring(j, i + 1);
                if (!seen.contains(sub)) {
                    seen.add(sub);
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
        }
    }
    return dp[n - 1];
}

