public String getSmallestString(int n, int k) {
    char[] arr = new char[n];
    Arrays.fill(arr, 'a');
    int i = n - 1;
    while (k > 0) {
        int rem = k % 26;
        if (rem == 0) rem = 26;
        arr[i] = (char)('a' + (rem - 1));
        k = k / 26;
        i--;
    }
    return new String(arr);
}

