    }
    return new String(chars);
}

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    char currentChar = 'a';
    while (k > 0) {
        int remainingValue = k - (currentChar - 'a' + 1);
        if (remainingValue <= 0) {
            sb.append(currentChar);
            k = 0;
        } else if (remainingValue <= 26) {
            sb.append(currentChar + (char)('a' + remainingValue - 1));
            k = 0;
        } else {
            sb.append(currentChar);
            k = remainingValue - 26;
        }
        currentChar++;
    }
    return sb.toString();
}

