    String ans = "";
    for (int i = 0; i < n; i++) {
        ans += (char)((k - i * (n - i)) / (n - i - 1) + 'a' - 1);
        k -= (ans.charAt(i) - 'a' + 1) * (n - i - 1);
    }
    return ans;
}

