    if (points.length != 3) return false;
    int[] p1 = points[0], p2 = points[1], p3 = points[2];
    return (p1[0] * p2[1] + p2[0] * p3[1] + p3[0] * p1[1]) == (p1[1] * p2[0] + p2[1] * p3[0] + p3[1] * p1[0]);
}

public static boolean isBoomerang(int[][] points) {
      if (points.length != 3) return false;
      int[] a = points[0];
      int[] b = points[1];
      int[] c = points[2];
      int ab = Math.sqrt((a[0] - b[0]) * (a[0] - b[0]) + (a[1] - b[1]) * (a[1] - b[1]));
      int bc = Math.sqrt((b[0] - c[0]) * (b[0] - c[0]) + (b[1] - c[1]) * (b[1] - c[1]));
      int ca = Math.sqrt((c[0] - a[0]) * (c[0] - a[0]) + (c[1] - a[1]) * (c[1] - a[1]));
      return ab == bc && bc == ca;
    }

