public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Check if the three points are collinear
    if (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2) == 0) {
        return false;
    }

    // Check if the triangle formed by the three points is oriented counterclockwise
    if (x1 * (y2 - y3) - x2 * (y3 - y1) + x3 * (y1 - y2) >= 0) {
        return false;
    }

    // Check if the triangle formed by the three points is oriented clockwise
    if (Math.abs(x1 * (y2 - y3) - x2 * (y3 - y1) + x3 * (y1 - y2)) < 1e-6) {
        return false;
    }

    return true;
}

