public static int calculateEnergy(String s) {
    int energy = 0;
    char currentChar = s.charAt(0);
    int currentStart = 0;
    int currentEnd = 0;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentEnd += 1;
        } else {
            if (currentEnd - currentStart > energy) {
                energy = currentEnd - currentStart;
            }
            currentChar = s.charAt(i);
            currentStart = i;
            currentEnd = i;
        }
    }
    if (currentEnd - currentStart > energy) {
        energy = currentEnd - currentStart;
    }
    return energy;
}

