public static List<Integer> lexicalOrder(int n) {
    List<Integer> list = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        list.add(i);
    }
    for (int i = 10; i <= n; i++) {
        String s = String.valueOf(i);
        int index = Collections.binarySearch(list, s);
        list.add(index < 0 ? -index - 1 : index, i);
    }
    return list;
}

