public static int minPerfectSquareSum(int n) {
    int result = 0;
    for (int i = 1; i * i <= n; i++) {
        result++;
        n -= i * i;
    }
    return result;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int sqrt = (int) Math.sqrt(n);
        count++;
        n -= sqrt * sqrt;
    }
    return count;
}

